nd,kA=function(_,_,_)local function RR(R,v)local RR,Rv,Rk,Rb=0,1,0,0;while Rk<(RR*0X2-RR)-(RR-1)do if R<=0 and v<=0 then Rk=Rk+1 else Rb=((R%2)+(v%0X2))%2 RR=RR+Rb*Rv R=(R-(R%0X02))/2 v=(v-(v%0X00002))/2 Rv=Rv+Rv;end;end;return RR;end;local function Rv(R,v)local Rv,Rk,RR=2^v,0,0;while Rk<(RR*0X2-RR)-(RR-1)do RR=((R*(256/Rv))%0X00100)+((R-(R%Rv))/Rv)Rk=Rk+1;end;return RR;end;return RR,Rv;end
